/**
 * SPIKE: Isaac / Perceptron Mk1 to EDL Generator
 * 
 * This script demonstrates how to take a JSON payload adhering to the
 * VIDEO_ANALYSIS_RESULT.schema.json contract (generated by Perceptron Mk1 or Isaac)
 * and compile it into a standard CMX3600 Edit Decision List (EDL).
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Helper to convert seconds to HH:MM:SS:FF (assuming 24fps)
function secondsToTimecode(totalSeconds, fps = 24) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = Math.floor(totalSeconds % 60);
    const frames = Math.floor((totalSeconds % 1) * fps);

    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frames).padStart(2, '0')}`;
}

/**
 * Generate a CMX3600 EDL from a VideoAnalysisResult object.
 * @param {Object} analysisResult Payload adhering to VIDEO_ANALYSIS_RESULT.schema.json
 * @param {string} tapeName Identifier for the source tape/file
 * @param {number} fps Frames per second of the source
 * @returns {string} CMX3600 EDL formatted string
 */
export function generateCMX3600EDL(analysisResult, tapeName = 'AX', fps = 24) {
    if (!analysisResult || !analysisResult.events) {
        throw new Error('Invalid analysis result: missing events array.');
    }

    let edl = `TITLE: Perceptron MK1 Auto-Clip Extraction\nFCM: NON-DROP FRAME\n\n`;
    
    // In a real EDL, sequence timecode accumulates. 
    // For extraction/dailies strings, we often just map Source IN/OUT to Record IN/OUT linearly.
    let currentRecordSeconds = 0;

    analysisResult.events.forEach((event, index) => {
        // Only process events with confidence above threshold or specific tags
        if (event.confidence < 0.7) return;

        const eventNumber = String(index + 1).padStart(3, '0');
        const sourceIn = secondsToTimecode(event.start_timecode, fps);
        const sourceOut = secondsToTimecode(event.end_timecode, fps);
        
        const duration = event.end_timecode - event.start_timecode;
        
        const recordIn = secondsToTimecode(currentRecordSeconds, fps);
        const recordOut = secondsToTimecode(currentRecordSeconds + duration, fps);
        
        // Advance sequence time
        currentRecordSeconds += duration;

        // CMX3600 standard line: 
        // EVENT  TAPE_NAME  TRACKS  TRANSITION  DUR  SRC_IN  SRC_OUT  REC_IN  REC_OUT
        edl += `${eventNumber}  ${tapeName}       V     C        000 ${sourceIn} ${sourceOut} ${recordIn} ${recordOut}\n`;
        edl += `* FROM CLIP NAME:  ${analysisResult.video_reference || 'UNKNOWN'}\n`;
        edl += `* LOC: ${sourceIn} ${event.tags ? event.tags.join(',') : ''} \n`;
        edl += `* MK1 DESC: ${event.description}\n\n`;
    });

    return edl;
}

// Example Execution
if (process.argv[1] === fileURLToPath(import.meta.url)) {
    const mockAnalysisResult = {
        timestamp: new Date().toISOString(),
        model: "isaac-edge-v2",
        video_reference: "cam_a_pink_pony_club.mp4",
        overall_summary: "Live performance clip extraction.",
        edl_export_ready: true,
        events: [
            {
                event_id: "evt_001",
                start_timecode: 14.5,
                end_timecode: 28.0,
                description: "Artist walks to center stage and begins performing.",
                confidence: 0.95,
                tags: ["highlight", "performance_start"]
            },
            {
                event_id: "evt_002",
                start_timecode: 65.2,
                end_timecode: 80.0,
                description: "Guitar solo with heavy physical movement and crowd interaction.",
                confidence: 0.88,
                physical_properties: {
                    "energy_level": "high",
                    "spatial_movement": "rapid_lateral"
                },
                tags: ["guitar_solo", "high_energy"]
            }
        ]
    };

    console.log("Generating EDL from mock Perceptron/Isaac output...\n");
    const edlOutput = generateCMX3600EDL(mockAnalysisResult, 'CAM_A', 24);
    console.log(edlOutput);
}
